// Renders the Microsoft Store screenshots from the shared view.
//
// Why not a screenshot of the running app: the Store listing's images are claims about a build,
// and a hand-taken capture can only show the machine it was taken on. This renders the same view
// the app shows, at the same 730x237 geometry, from the commit being packaged - so the images can
// be regenerated by a script, in CI, on any machine, and pack-msix.ps1 can refuse a set that is
// older than the source it is meant to describe.
//
// usage: SaSur.StoreShots <output-directory>

using Avalonia;
using Avalonia.Controls;
using Avalonia.Headless;
using Avalonia.Media;
using Avalonia.Media.Imaging;
using Avalonia.Styling;
using Avalonia.Themes.Fluent;
using SaSur.Core;
using SaSur.Ui;

internal static class Program
{
    // 1366x768: the Store's own floor, and the size the listing has used since 1.1. The window is
    // drawn at 1:1 inside it - a bitmap render at a 192 DPI is scaled twice by the Avalonia
    // renderer and comes out cropped, and an upscaled 1x render is a blurred claim about the UI
    // rather than a picture of it.
    private const int CanvasWidth = 1366;
    private const int CanvasHeight = 768;

    private static int Main(string[] args)
    {
        var output = args.Length > 0
            ? args[0]
            : Path.Combine(AppContext.BaseDirectory, "screenshots");
        Directory.CreateDirectory(output);

        AppBuilder.Configure<ShotApp>()
            .UseSkia()
            .UseHeadless(new AvaloniaHeadlessPlatformOptions { UseHeadlessDrawing = false })
            .SetupWithoutStarting();

        foreach (var mode in new[] { ThemeMode.Light, ThemeMode.Dark })
        {
            var name = mode == ThemeMode.Light ? "light" : "dark";
            var path = Path.Combine(output, $"SA-Sur_store_{name}_{CanvasWidth}x{CanvasHeight}.png");

            using (var shot = Render(mode))
            {
                shot.Save(path);
            }

            var info = new FileInfo(path);
            Console.WriteLine($"{path}  {info.Length:N0} bytes");
        }

        return 0;
    }

    private static RenderTargetBitmap Render(ThemeMode mode)
    {
        var settings = new AppSettings
        {
            FilePath = Path.Combine(Path.GetTempPath(), $"sa-sur-shot-{Guid.NewGuid():N}.json"),
            Appearance = mode,
        };

        var view = new SaSurView(new SilentToneOutput(), settings);

        // A real window, because that is what resolves the theme variant: the view sets it on the
        // top level as well as on the application, and a control outside a window has no top level.
        var window = new Window
        {
            Width = SaSurView.WindowWidth,
            Height = SaSurView.WindowHeight,
            SystemDecorations = SystemDecorations.None,
            Content = view,
        };
        window.Show();
        Avalonia.Threading.Dispatcher.UIThread.RunJobs();

        var content = new PixelSize(
            (int)SaSurView.WindowWidth,
            (int)SaSurView.WindowHeight);

        var windowShot = new RenderTargetBitmap(content, new Vector(96, 96));
        windowShot.Render(window);

        var canvas = new RenderTargetBitmap(new PixelSize(CanvasWidth, CanvasHeight), new Vector(96, 96));
        using (var ctx = canvas.CreateDrawingContext())
        {
            var (top, bottom) = mode == ThemeMode.Light
                ? (Color.FromRgb(0xED, 0xF0, 0xF3), Color.FromRgb(0xD6, 0xDB, 0xE0))
                : (Color.FromRgb(0x51, 0x54, 0x59), Color.FromRgb(0x38, 0x3B, 0x3F));

            var backdrop = new LinearGradientBrush
            {
                StartPoint = new RelativePoint(0, 0, RelativeUnit.Relative),
                EndPoint = new RelativePoint(0, 1, RelativeUnit.Relative),
                GradientStops =
                {
                    new GradientStop(top, 0),
                    new GradientStop(bottom, 1),
                },
            };
            ctx.DrawRectangle(backdrop, null, new Rect(0, 0, CanvasWidth, CanvasHeight));

            var left = (CanvasWidth - content.Width) / 2.0;
            var topEdge = (CanvasHeight - content.Height) / 2.0;
            var frame = new Rect(left, topEdge, content.Width, content.Height);

            var shadow = new BoxShadows(new BoxShadow
            {
                OffsetX = 0,
                OffsetY = 14,
                Blur = 40,
                Color = Color.FromArgb(70, 0, 0, 0),
            });
            ctx.DrawRectangle(null, null, frame, 0, 0, shadow);
            ctx.DrawImage(windowShot, frame);
        }

        window.Close();
        windowShot.Dispose();
        return canvas;
    }
}

/// The application the shots are rendered inside. Its only job is a theme: without one the
/// view's own theme dictionaries resolve but Fluent's control templates do not.
public sealed class ShotApp : Application
{
    public override void Initialize() => Styles.Add(new FluentTheme());
}
